```js
(function () {
'use strict';
var S = window.SURVEY;
var DIM = {}; S.dims.forEach(d => DIM[d.id] = d);

// ---------- 快照与轨迹（归属 + 可回退） ----------
function clone(o){ return JSON.parse(JSON.stringify(o)); }
var t0 = new Date();
function tsfmt(d){ ... HH:MM:SS }
var state;             // 当前已提交状态
var trail = [];        // [{seq, time, action, source, snap}]
var tIndex = -1;       // 当前所处轨迹位置

function snapshot(){ return {x:state.x, y:state.y, measure:clone(state.measure), filters:clone(state.filters), focus:state.focus}; }
function commit(action, source, mutate){
  // 截断当前位置之后的重做分支
  trail = trail.slice(0, tIndex+1);
  mutate();
  trail.push({seq: trail.length, time: new Date(), action, source, snap: snapshot()});
  tIndex = trail.length - 1;
  renderAll();
}
function timeTravel(i){
  if(i<0 || i>=trail.length || i===tIndex) return;
  tIndex = i;
  state = clone(trail[i].snap);
  renderAll();
}
function undo(){ timeTravel(tIndex-1); }
function redo(){ timeTravel(tIndex+1); }
```

Wait — snapshot() reads from `state`; commit mutates state then snapshots. timeTravel sets state from snapshot. Also "回到初始" = timeTravel(0).

Init: state = {x:'method', y:'temp', measure:{kind:'count', dim:null}, filters:[], focus:null}; trail=[{seq:0,time:t0,action:'初始状态（首屏内联就绪）',source:'系统 · 首屏内联',snap:snapshot()}]; tIndex=0.

