1	#!/usr/bin/env node
2	/**
3	 * prax-measure CLI (spec §5.1):
4	 *   node bin/prax-measure.mjs --app <appDir> --out <sessionDir>
5	 *       [--serve <url>] [--viewports 1280x860,1440x900] [--entry /path]
6	 *       [--session-id <id>] [--scenario <label>]
7	 *       [--ready-selector <selector>] [--ready-timeout-ms <ms>]
8	 * Exit codes: 0 = no error-severity fail; 1 = error-severity fail;
9	 *             2 = incomplete measurement, invalid target or invocation failure.
10	 */
11	import { readFile } from "node:fs/promises";
12	import { runMeasurement } from "../dist/runner.js";
13	
14	function parseViewports(raw) {
15	  return raw
16	    .split(",")
17	    .map((entry) => entry.trim())
18	    .filter((entry) => entry !== "")
19	    .map((entry) => {
20	      const match = entry.match(/^(\d+)x(\d+)(?::(\w+))?$/);
21	      if (match === null) throw new Error(`invalid viewport '${entry}' (expected WxH[:label])`);
22	      return { width: Number(match[1]), height: Number(match[2]), ...(match[3] === undefined ? {} : { label: match[3] }) };
23	    });
24	}
25	
26	function argumentValue(name) {
27	  const index = process.argv.indexOf(name);
28	  if (index === -1) return undefined;
29	  const value = process.argv[index + 1];
30	  if (value === undefined || value.startsWith("--")) return undefined;
31	  return value;
32	}
33	
34	const app = argumentValue("--app");
35	const out = argumentValue("--out");
36	const serve = argumentValue("--serve");
37	const entry = argumentValue("--entry");
38	const readySelector = argumentValue("--ready-selector");
39	const readyTimeout = argumentValue("--ready-timeout-ms");
40	const sessionId = argumentValue("--session-id");
41	const scenario = argumentValue("--scenario");
42	const viewportsRaw = argumentValue("--viewports") ?? "1280x860";
43	
44	if (app === undefined || out === undefined) {
45	  console.error("usage: prax-measure --app <appDir> --out <sessionDir> [--entry /path] [--serve <url>] [--viewports 1280x860,1440x900] [--session-id <id>] [--scenario <label>] [--ready-selector <selector>] [--ready-timeout-ms <ms>]");
46	  process.exit(2);
47	}
48	
49	try {
50	  const receiptPath = await runMeasurement({
51	    appDir: app,
52	    outDir: out,
53	    serve,
54	    viewports: parseViewports(viewportsRaw),
55	    ...(entry === undefined ? {} : { entry }),
56	    ...(readySelector === undefined ? {} : { readySelector }),
57	    ...(readyTimeout === undefined ? {} : { readyTimeoutMs: Number(readyTimeout) }),
58	    ...(sessionId === undefined ? {} : { sessionId }),
59	    ...(scenario === undefined ? {} : { scenario }),
60	  });
61	  const receipt = JSON.parse(await readFile(receiptPath, "utf8"));
62	  const incomplete = receipt.checks.some((check) => check.status === "skipped");
63	  const errorFailures = receipt.checks.filter((check) => check.status === "fail" && check.severity === "error");
64	  console.log(`receipt: ${receiptPath}`);
65	  console.log(
66	    `summary: pass=${receipt.summary.pass} fail=${receipt.summary.fail} skipped=${receipt.summary.skipped} warnings=${receipt.summary.warnings}`,
67	  );
68	  for (const check of receipt.checks.filter((entry) => entry.status !== "pass")) {
69	    console.log(`  ${check.status} ${check.id}${check.reason !== undefined ? ` (${check.reason})` : ""}`);
70	  }
71	  process.exit(errorFailures.length > 0 ? 1 : incomplete ? 2 : 0);
72	} catch (error) {
73	  console.error(`prax-measure failed: ${error instanceof Error ? error.message : String(error)}`);
74	  process.exit(2);
75	}
