1	import { createHash } from "node:crypto";
2	import { mkdir, readFile } from "node:fs/promises";
3	import { join } from "node:path";
4	import type { Page } from "playwright";
5	import { ARTIFACT_CHECK_DEFAULT_SEVERITY } from "prax-validator";
6	import type { MeasurementReceipt } from "prax-validator";
7	
8	export interface CheckContext {
9	  viewport: { width: number; height: number; label?: string | undefined };
10	  screenshotDir: string; // absolute; check writes PNGs here, refs are rebased by the runner
11	}
12	
13	export type CheckOutcome = MeasurementReceipt["checks"][number];
14	
15	/**
16	 * layout.overflow (spec §5.3): page-level horizontal overflow
17	 * (documentElement.scrollWidth <= innerWidth) plus element-level content
18	 * overflow (visible elements with scrollWidth > clientWidth + 1, the 1px
19	 * rounding tolerance). Screenshot captured on fail.
20	 */
21	export async function run(page: Page, ctx: CheckContext): Promise<CheckOutcome> {
22	  const viewportLabel = ctx.viewport.label ?? `${ctx.viewport.width}x${ctx.viewport.height}`;
23	  const measurement = await page.evaluate(() => {
24	    const isVisible = (element: Element): boolean => {
25	      const style = window.getComputedStyle(element);
26	      return style.display !== "none" && style.visibility !== "hidden";
27	    };
28	    const flagged: string[] = [];
29	    const candidates: Element[] = [document.documentElement, document.body, ...Array.from(document.body?.querySelectorAll("*") ?? [])];
30	    for (const element of candidates) {
31	      if (element === null || !isVisible(element)) continue;
32	      // sr-only clip pattern: a sub-pixel box is assistive-tech text, not rendered content
33	      const box = element.getBoundingClientRect();
34	      if (box.width <= 1 || box.height <= 1) continue;
35	      if (element.scrollWidth > element.clientWidth + 1) {
36	        flagged.push(
37	          element.id !== ""
38	            ? `${element.tagName.toLowerCase()}#${element.id}`
39	            : element.tagName.toLowerCase(),
40	        );
41	      }
42	    }
43	    return {
44	      scroll_width: document.documentElement.scrollWidth,
45	      inner_width: window.innerWidth,
46	      flagged,
47	    };
48	  });
49	
50	  const overflowPx = Math.max(0, measurement.scroll_width - measurement.inner_width);
51	  const threshold = { max_overflow_px: 0, element_overflow_tolerance_px: 1 };
52	  const measured = {
53	    scroll_width: measurement.scroll_width,
54	    inner_width: measurement.inner_width,
55	    overflow_px: overflowPx,
56	    element_overflows: measurement.flagged.length,
57	    flagged_elements: measurement.flagged,
58	    viewport: viewportLabel,
59	  };
60	
61	  if (overflowPx <= 0 && measurement.flagged.length === 0) {
62	    return {
63	      id: "layout.overflow",
64	      status: "pass",
65	      severity: ARTIFACT_CHECK_DEFAULT_SEVERITY["layout.overflow"],
66	      measured,
67	      threshold,
68	      evidence_refs: [],
69	      supported_fixes: [],
70	    };
71	  }
72	
73	  const fileName = `overflow-${ctx.viewport.width}x${ctx.viewport.height}.png`;
74	  await mkdir(ctx.screenshotDir, { recursive: true });
75	  await page.screenshot({ path: join(ctx.screenshotDir, fileName), fullPage: false });
76	  const sha256 = createHash("sha256")
77	    .update(await readFile(join(ctx.screenshotDir, fileName)))
78	    .digest("hex");
79	
80	  return {
81	    id: "layout.overflow",
82	    status: "fail",
83	    severity: ARTIFACT_CHECK_DEFAULT_SEVERITY["layout.overflow"],
84	    subject: "document.documentElement",
