$script = @'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
await page.goto('file:///E:/codex-prj/ab-worktrees/pi-matrix-m4/s3-p1/index.html');
await page.waitForSelector('.heat');
const hits = await page.evaluate(() => {
  const out = [];
  for (const el of document.querySelectorAll('*')) {
    const cs = getComputedStyle(el);
    if (cs.color === 'rgb(134, 149, 166)' || cs.color === 'rgb(217, 226, 236)') {
      let node = el, bg = null, chain = [];
      while (node && node !== document.documentElement) {
        const b = getComputedStyle(node).backgroundColor;
        chain.push(node.tagName + ':' + b);
        if (b && b !== 'rgba(0, 0, 0, 0)' && b !== 'transparent') { bg = b; break; }
        node = node.parentElement;
      }
      if (bg === 'rgb(241, 250, 255)') out.push({ tag: el.tagName, cls: el.className && el.className.baseVal !== undefined ? 'svg' : el.className, text: (el.textContent || '').slice(0, 24), chain: chain.slice(0, 5).join(' <- ') });
    }
  }
  return out;
});
console.log(JSON.stringify(hits, null, 1));
await browser.close();
