1	import { createHash } from "node:crypto";
2	import { mkdir, readFile } from "node:fs/promises";
3	import { join } from "node:path";
4	import type { Page } from "playwright";
5	import { ARTIFACT_CHECK_DEFAULT_SEVERITY } from "prax-validator";
6	import type { MeasurementReceipt } from "prax-validator";
7	
8	export interface CheckContext {
9	  viewport: { width: number; height: number; label?: string | undefined };
10	  screenshotDir: string; // absolute; check writes PNGs here, refs are rebased by the runner
11	}
12	
13	export type CheckOutcome = MeasurementReceipt["checks"][number];
14	
15	/**
16	 * a11y.contrast (spec §5.3): visible text contrast against its effective
17	 * background (walks ancestors for the first opaque background, accounts for
18	 * opacity) under WCAG 2.2 AA — 4.5:1 normal text, 3.0:1 large text (≥24px, or
19	 * ≥18.66px bold). Error-born severity: a normative obligation with no
20	 * overkill risk.
21	 */
22	export async function run(page: Page, ctx: CheckContext): Promise<CheckOutcome> {
23	  const viewportLabel = ctx.viewport.label ?? `${ctx.viewport.width}x${ctx.viewport.height}`;
24	  const pairs: Array<{
25	    selector: string;
26	    ratio: number;
27	    required: number;
28	    font_px: number;
29	    bold: boolean;
30	    foreground: string;
31	    background: string;
32	  }> = await page.evaluate(() => {
33	    const parseColor = (value: string): [number, number, number, number] | undefined => {
34	      const match = value.match(/rgba?\(([^)]+)\)/);
35	      if (match === null) return undefined;
36	      const parts = match[1]!.split(",").map((part) => Number.parseFloat(part.trim()));
37	      return [parts[0]!, parts[1]!, parts[2]!, parts[3] === undefined ? 1 : parts[3]!];
38	    };
39	    const blend = (over: [number, number, number, number], under: [number, number, number]): [number, number, number] => {
40	      const alpha = over[3];
41	      return [
42	        over[0]! * alpha + under[0]! * (1 - alpha),
43	        over[1]! * alpha + under[1]! * (1 - alpha),
44	        over[2]! * alpha + under[2]! * (1 - alpha),
45	      ];
46	    };
47	    const luminance = (rgb: [number, number, number]): number => {
48	      const channels = rgb.map((channel) => {
49	        const scaled = channel / 255;
50	        return scaled <= 0.04045 ? scaled / 12.92 : ((scaled + 0.055) / 1.055) ** 2.4;
51	      }) as [number, number, number];
52	      return 0.2126 * channels[0]! + 0.7152 * channels[1]! + 0.0722 * channels[2]!;
53	    };
54	    const contrast = (a: [number, number, number], b: [number, number, number]): number => {
55	      const l1 = luminance(a);
56	      const l2 = luminance(b);
57	      const [hi, lo] = l1 >= l2 ? [l1, l2] : [l2, l1];
58	      return (hi + 0.05) / (lo + 0.05);
59	    };
60	    const describe = (element: Element): string => {
61	      const tag = element.tagName.toLowerCase();
62	      return element.id !== "" ? `${tag}#${element.id}` : tag;
63	    };
64	
65	    const failing: typeof pairs = [];
66	    for (const element of Array.from(document.body?.querySelectorAll("*") ?? [])) {
67	      const style = window.getComputedStyle(element);
68	      if (style.display === "none" || style.visibility === "hidden") continue;
69	      // sr-only clip pattern: a sub-pixel box is assistive-tech text, not rendered content
70	      const box = element.getBoundingClientRect();
71	      if (box.width <= 1 || box.height <= 1) continue;
72	      const ownText = Array.from(element.childNodes)
73	        .filter((node) => node.nodeType === Node.TEXT_NODE)
74	        .map((node) => node.textContent ?? "")
75	        .join("")
76	        .trim();
77	      if (ownText === "") continue;
78	
79	      // effective background: nearest ancestor with a non-transparent color,
80	      // composited onto the canvas default (white) when itself translucent
81	      let background: [number, number, number] = [255, 255, 255];
82	      for (let ancestor: Element | null = element; ancestor !== null; ancestor = ancestor.parentElement) {
83	        const parsed = parseColor(window.getComputedStyle(ancestor).backgroundColor);
84	        if (parsed === undefined) continue;
85	        if (parsed[3] >= 1) {
86	          background = [parsed[0]!, parsed[1]!, parsed[2]!];
87	          break;
88	        }
89	        if (parsed[3] > 0) {
90	          background = blend(parsed, background);
91	          break;
92	        }
93	      }
94	
95	      // effective foreground: the element's color, composited over the
96	      // background by its accumulated opacity chain
97	      const foregroundParsed = parseColor(style.color) ?? [0, 0, 0, 1];
98	      let opacity = 1;
99	      for (let node: Element | null = element; node !== null; node = node.parentElement) {
100	        opacity *= Number.parseFloat(window.getComputedStyle(node).opacity || "1");
101	      }
102	      const foreground = blend([foregroundParsed[0]!, foregroundParsed[1]!, foregroundParsed[2]!, opacity], background);
103	
104	      const fontPx = Number.parseFloat(style.fontSize);
105	      const bold = style.fontWeight === "bold" || Number.parseInt(style.fontWeight, 10) >= 600;
106	      const required = fontPx >= 24 || (fontPx >= 18.66 && bold) ? 3.0 : 4.5;
107	      const ratio = contrast(foreground, background);
108	      if (ratio < required) {
109	        failing.push({
110	          selector: describe(element),
111	          ratio: Math.round(ratio * 100) / 100,
112	          required,
113	          font_px: fontPx,
114	          bold,
115	          foreground: style.color,
116	          background: `rgb(${Math.round(background[0]!)},${Math.round(background[1]!)},${Math.round(background[2]!)})`,
117	        });
118	      }
119	    }
120	    return failing;
121	  });
122	
123	  const measured = {
124	    failing: pairs.length,
125	    pairs,
126	    viewport: viewportLabel,
127	  };
128	  const threshold = { normal_min_ratio: 4.5, large_min_ratio: 3.0 };
129	
130	  if (pairs.length === 0) {
131	    return {
132	      id: "a11y.contrast",
133	      status: "pass",
134	      severity: ARTIFACT_CHECK_DEFAULT_SEVERITY["a11y.contrast"],
135	      measured,
136	      threshold,
137	      evidence_refs: [],
138	      supported_fixes: [],
139	    };
140	  }
141	
142	  const fileName = `contrast-${ctx.viewport.width}x${ctx.viewport.height}.png`;
143	  await mkdir(ctx.screenshotDir, { recursive: true });
144	  await page.screenshot({ path: join(ctx.screenshotDir, fileName), fullPage: true });
145	  const sha256 = createHash("sha256")
146	    .update(await readFile(join(ctx.screenshotDir, fileName)))
147	    .digest("hex");
148	
149	  return {
150	    id: "a11y.contrast",
151	    status: "fail",
152	    severity: ARTIFACT_CHECK_DEFAULT_SEVERITY["a11y.contrast"],
153	    subject: pairs.map((pair) => pair.selector).join("; "),
154	    measured,
155	    threshold,
156	    evidence_refs: [{ ref: `validation-evidence/${fileName}`, sha256 }],
157	    supported_fixes: [
158	      "darken the failing text color (or lighten it against a dark background) until the measured ratio meets the required minimum",
159	    ],
160	  };
161	}
162

