$script = @'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
await page.goto('file:///E:/codex-prj/ab-worktrees/pi-matrix-m4/s3-p1/index.html');
await page.waitForSelector('.heat');
const res = await page.evaluate(() => {
  const parseColor = (v) => { const m = v.match(/rgba?\(([^)]+)\)/); if (!m) return undefined; const p = m[1].split(',').map(Number.parseFloat); return [p[0], p[1], p[2], p[3] === undefined ? 1 : p[3]]; };
  const out = [];
  for (const element of Array.from(document.body.querySelectorAll('*'))) {
    const style = getComputedStyle(element);
    if (style.display === 'none' || style.visibility === 'hidden') continue;
    const box = element.getBoundingClientRect();
    if (box.width <= 1 || box.height <= 1) continue;
    const ownText = Array.from(element.childNodes).filter(n => n.nodeType === 3).map(n => n.textContent).join('').trim();
    if (ownText === '') continue;
    let background = [255, 255, 255];
    for (let a = element; a !== null; a = a.parentElement) {
      const p = parseColor(getComputedStyle(a).backgroundColor);
      if (p === undefined) continue;
      if (p[3] >= 1) { background = [p[0], p[1], p[2]]; break; }
      if (p[3] > 0) { background = [p[0]*p[3]+background[0]*(1-p[3]), p[1]*p[3]+background[1]*(1-p[3]), p[2]*p[3]+background[2]*(1-p[3])]; break; }
    }
    const bgStr = 'rgb(' + background.map(Math.round).join(',') + ')';
    if (bgStr === 'rgb(241,250,255)') out.push({ tag: element.tagName, cls: String(element.className).slice(0, 40), text: ownText.slice(0, 30), html: element.outerHTML.slice(0, 120), color: style.color, font: style.fontSize });
  }
  return out;
});
console.log(JSON.stringify(res, null, 1));
await browser.close();
